"""Write dist/shark-photos.js from photos.json (credits for every photo)."""
import json
d = json.load(open('/home/claude/photos/photos.json'))
out = {k: [{'file': 'sharks/' + p['file'], 'credit': p['credit'], 'page': p['page'], 'license': p['license']} for p in v] for k, v in d.items()}
open('/home/claude/shark-academy/dist/shark-photos.js', 'w').write(
    '/* Licensed shark photos from Wikimedia Commons, chosen for clear views of the whole shark.\n'
    ' * Generated by research/photos/build.py. First photo is the main picture. */\n'
    'const sharkPhotoData = ' + json.dumps(out, indent=1, ensure_ascii=False) + ';\n')
print({k: len(v) for k, v in out.items()})
